<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-chart-line text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Reaction Yield Calc</h5><p class="text-muted small mb-0">Calculate actual, theoretical, and percent yield</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Actual Yield (g)</label><input type="number" id="in-a" class="form-control form-control-lg" value="7.2" step="0.01"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Theoretical Yield (g)</label><input type="number" id="in-t" class="form-control form-control-lg" value="10" step="0.01"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Molar Mass Product (g/mol)</label><input type="number" id="in-mm" class="form-control form-control-lg" value="18.015" step="0.001"></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Formula:</b> %Yield = (Actual/Theoretical) × 100</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var a=parseFloat(document.getElementById("in-a").value)||0,t=parseFloat(document.getElementById("in-t").value)||0,mm=parseFloat(document.getElementById("in-mm").value)||1;if(t===0)return;var pct=(a/t)*100,molA=a/mm,molT=t/mm;document.getElementById("out-main").textContent=pct.toFixed(2)+"%";document.getElementById("out-unit").textContent="Percent Yield";document.getElementById("out-detail").innerHTML='<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Actual mol</div><div class="h5 fw-bold mb-0 text-primary">'+molA.toFixed(4)+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Theoretical mol</div><div class="h5 fw-bold mb-0 text-info">'+molT.toFixed(4)+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Lost</div><div class="h5 fw-bold mb-0 text-danger">'+(t-a).toFixed(2)+' g</div></div></div>';var ins=["("+a+"/"+t+")×100 = <b>"+pct.toFixed(2)+"%</b>"];if(pct>100)ins.push("⚠ >100% indicates impurities");else if(pct>90)ins.push("Excellent yield");document.getElementById("out-ins").innerHTML='<ul class="list-unstyled mb-0">'+ins.map(function(x){return'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+"</li>";}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-a").value=7.2;document.getElementById("in-t").value=10;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Yield: "+document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script>